def test_get_repr_function():
    def repr_int(item):
        return 'integer: {}'.format(item)

    def repr_negative(item):
        return 'negative: {}'.format(item)

    custom_repr = (
        (lambda item: isinstance(item, int) and item < 0, repr_negative),
        (int, repr_int),
    )

