def test_WritableStream_write():
    # WritableStream cannot be instantiated without implementing write().
    try:
        WritableStream()
    except TypeError:
        pass
    else:
        raise AssertionError(
            "WritableStream should not be instantiable while write() is abstract"
        )

    class ConcreteWritableStream(WritableStream):
        def __init__(self):
            self.data = []

        def write(self, s):
            self.data.append(s)
            return len(s)

    stream = ConcreteWritableStream()

    assert stream.write("hello") == 5
    assert stream.data == ["hello"]

